// 一次批量保存从发出到本次结果处理结束期间为 true：期间只能有这一次请求，
// 勾选变化与表单重复提交都不能解除或新增请求。
let batchSaving = false;

function syncSubmitState() {
  const btn = document.getElementById("batch-submit");
